#include<bits/stdc++.h>

using namespace std;
using pi=pair<int,int>;

int main(){
  int n,q;
  cin >> n >> q;
  multiset<pi> st;
  for(int i=1;i<=n;i++){
    st.insert({i,1});
  }
  while(q--){
    int x,y;
    cin >> x >> y;
    int res=0;
    while(!st.empty()){
      auto it=st.begin();
      if((*it).first>x){break;}
      res+=(*it).second;
      st.erase(it);
    }
    if(st.size()>0){ st.insert({y,res}); }
    cout << res << "\n";
  }
  return 0;
}

#include<bits/stdc++.h>

using namespace std;
using pi=pair<int,int>;

int main(){
  int n,q;
  cin >> n >> q;
  priority_queue<pi,vector<pi>,greater<pi>> pq;
  for(int i=1;i<=n;i++){
    pq.push({i,1});
  }
  while(q--){
    int x,y;
    cin >> x >> y;
    int res=0;
    while(!pq.empty()){
      if(pq.top().first>x){break;}
      res+=pq.top().second; pq.pop();
    }
    if(res>0){ pq.push({y,res}); }
    cout << res << "\n";
  }
  return 0;
}

#include<bits/stdc++.h>
#include<atcoder/lazysegtree>

using namespace std;
using namespace atcoder;

using ll=long long;

struct S{
  ll val,len;
};
using F=ll;

const F ID=8e18;

S op(S a,S b){ return {a.val+b.val,a.len+b.len}; }
S e(){ return {0,0}; }
S mapping(F f,S x){
  if(f!=ID){ x.val=f*x.len; }
  return x;
}
F composition(F f,F g){ return (f==ID)?g:f; }
F id(){ return ID; }

int main(){
  ll n,q;
  cin >> n >> q;
  vector<S> v(n+1,{1,1});
  v[0]={0,1};
  lazy_segtree<S, op, e, F, mapping, composition, id> seg(v);

  while(q--){
    ll x,y;
    cin >> x >> y;
    ll res=seg.prod(0,x+1).val;
    seg.apply(0,x+1,0);
    seg.set(y,{seg.get(y).val+res,1});
    cout << res << "\n";
  }
  return 0;
}
